#!/usr/bin/env bash
# Waybar: show power profile; "cycle" switches power-saver -> balanced -> performance  (generated by theme.py)
order=(power-saver balanced performance)
cur=$(powerprofilesctl get)
if [ "${1:-}" = cycle ]; then
  for i in "${!order[@]}"; do [ "${order[$i]}" = "$cur" ] && n=${order[$(( (i+1)%3 ))]}; done
  powerprofilesctl set "$n"; cur=$n; pkill -RTMIN+9 waybar
  case $cur in performance) m="Performance — full speed, fans louder";; balanced) m="Balanced";; *) m="Power saver — quiet, longer battery";; esac
  notify-send -t 1800 -h string:x-canonical-private-synchronous:powerprofile -i power-profile-$cur-symbolic "Power mode" "$m"
fi
case $cur in power-saver) i="󰌪";; balanced) i="󰗑";; *) i="󰓅";; esac
p=$(jq -r '.name // "auto"' ~/.local/state/myos/profile.json 2>/dev/null || echo auto)
case $p in ai) pl="AI work";; battery) pl="Battery";; present) pl="Presenting";; *) pl="Automatic";; esac
printf '{"text":"%s","tooltip":"Power mode: %s · Profile: %s\\nClick or Super+Shift+P: power mode · Super+Ctrl+P: profile","class":"%s"}\n' "$i" "$cur" "$pl" "$cur"
